"use strict";document.querySelectorAll("[data-api-copy]").forEach(button=>button.addEventListener("click",async()=>{const code=document.getElementById(button.dataset.apiCopy);const status=document.querySelector("[data-api-copy-status]");try{await navigator.clipboard.writeText(code.textContent);status.textContent="已复制，可粘贴到你的项目中。";}catch(e){status.textContent="浏览器未允许复制，请直接选中代码文本复制。";}}));